/*
 * A316342  Fibonacci word A003849 with first two terms replaced by 2's.
 * https://oeis.org/A316342
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(0)=2, a(1)=2, a(n)=FibWord(n) for n>=2, where FibWord(n) is
 *            the n-th character of the Fibonacci word over {0,1} generated by
 *            the morphism 0 → 01, 1 → 0
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static uint8_t *g_cache = NULL;
static idx_t g_len   = 0;

/* Recompute the cache up to index upto (inclusive).  The cache is
   stored as unsigned 8‑bit values 0,1,2. */
static void recompute_cache(idx_t upto)
{
    idx_t newlen = upto + 1;                   /* needed array length */
    uint8_t *newp = (uint8_t*)malloc(newlen * sizeof(uint8_t));
    if (!newp) abort();                       /* allocation failed */

    /* --- generate the Fibonacci word up to index upto --- */
    size_t cur_len = 1;
    uint8_t *cur   = (uint8_t*)malloc(sizeof(uint8_t));
    if (!cur) abort();
    cur[0] = 0;                                 /* start with '0' */

    while (cur_len <= (size_t)upto) {
        /* grow the word by one morphic step */
        size_t next_cap = cur_len * 2 + 4;        /* add a safety margin */
        uint8_t *next   = (uint8_t*)malloc(next_cap);
        if (!next) abort();
        size_t next_len = 0;
        for (size_t i = 0; i < cur_len; ++i) {
            if (cur[i] == 0) {                   /* 0 → 01 */
                next[next_len++] = 0;
                next[next_len++] = 1;
            } else {                              /* 1 → 0 */
                next[next_len++] = 0;
            }
        }
        free(cur);
        cur     = next;
        cur_len = next_len;
    }

    /* --- fill the cache: first two entries are 2, the rest are the word --- */
    newp[0] = 2;
    if (newlen >= 2) newp[1] = 2;
    for (idx_t i = 2; i < newlen; ++i) {
        newp[i] = cur[i];
    }

    free(cur);                      /* discard temporary word */

    /* --- replace old cache --- */
    if (g_cache) free(g_cache);
    g_cache = newp;
    g_len   = newlen;
}

seq_t a(idx_t n)
{
    if (n >= g_len) {
        recompute_cache(n);
    }
    return (seq_t)g_cache[n];
}
